    bool IRustVmBatchTarget.TryGetCollection(int collectionId, out RustVmBatchCollectionInfo collection)
    {
        collection = collectionId switch
        {
            1 => new RustVmBatchCollectionInfo(nameof(Processes), RustVmValueWireKind.Model, Processes),
            2 => new RustVmBatchCollectionInfo(nameof(CpuCores), RustVmValueWireKind.Model, CpuCores),
            _ => default,
        };
        return collection.Items is not null;
    }

    bool IRustVmBatchTarget.TryGetCommand(int commandId, out IRustVmBatchCommand command)
    {
        command = commandId switch
        {
            1 => RefreshCommand,
            2 => KillCommand,
            3 => PinCommand,
            4 => ShowDetailsCommand,
            5 => ToggleThemeCommand,
            6 => ToggleFreezeCommand,
            7 => SortProcessesCommand,
            8 => ConfirmKillCommand,
            9 => CancelKillCommand,
            10 => CloseDetailsCommand,
            11 => ShowParentDetailsCommand,
            12 => CopySelectedRowCommand,
            13 => ExitApplicationCommand,
            14 => ClearSearchCommand,
            15 => ToggleCpuOperatorCommand,
            16 => ToggleRamOperatorCommand,
            17 => ToggleRuntimeOperatorCommand,
            18 => ToggleFiltersCommand,
            19 => ToggleColumnsCommand,
            20 => ToggleSearchHelpCommand,
            21 => CycleRefreshRateCommand,
            22 => CloseOverlaysCommand,
            _ => null!,
        };
        return command is not null;
    }

    bool IRustVmBatchTarget.IsEnumValueDefined(int propertyId, long value) => propertyId switch
    {
        _ => false,
    };

    IDisposable IRustVmBatchTarget.CreateNestedProperty(int propertyId, IAvnRustViewModel model) => propertyId switch
    {
        _ => throw new ArgumentOutOfRangeException(nameof(propertyId)),
    };

    IDisposable IRustVmBatchTarget.CreateNestedElement(int collectionId, IAvnRustViewModel model) => collectionId switch
    {
        1 => new global::NeoHtop.Presentation.Generated.ProcessRowViewModelAdapter(model, _dispatch, _post),
        2 => new global::NeoHtop.Presentation.Generated.CpuCoreViewModelAdapter(model, _dispatch, _post),
        _ => throw new ArgumentOutOfRangeException(nameof(collectionId)),
    };

