    bool IRustVmBatchTarget.CommitError(string propertyName, string? message) =>
        RustVmBatchErrors.Set(_errors, propertyName, message);

    bool IRustVmTableSelectionBatchTarget.IsPostCollectionPropertyNotification(string propertyName, IReadOnlySet<string> changedCollections) => propertyName switch
    {
        nameof(SelectedIndex) => changedCollections.Contains(nameof(Processes)),
        nameof(SelectedKey) => changedCollections.Contains(nameof(Processes)),
        _ => false,
    };

    void IRustVmBatchTarget.RaisePropertyChanged(string propertyName) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));

    void IRustVmBatchTarget.RaiseErrorsChanged(string propertyName) =>
        ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));

    /// <summary>
    /// Enqueues one immutable batch. This call never reads the batch, applies it,
    /// or completes it on the submitting (Rust worker) stack.
    /// </summary>
    public int SubmitBatch(IAvnRustVmUpdateBatch? batch) => _batch.Submit(batch);

    /// <summary>
    /// Detaches the model and disposes every nested adapter exactly once. When a
    /// batch notification triggers this re-entrantly, the gate defers the cleanup
    /// until the batch's commit and notifications have finished.
    /// </summary>
    private static string CommandArgumentOrFallback(object? parameter, string fallback)
    {
        if (parameter is null)
            return fallback;
        return parameter switch
        {
            string text => text,
            bool flag => flag ? "true" : "false",
            IFormattable formattable => formattable.ToString(null, CultureInfo.InvariantCulture) ?? fallback,
            _ => parameter.ToString() ?? fallback,
        };
    }

    public void Dispose() => _batch.Dispose(DisposeCore);

    private void ApplyThemeVariant()
    {
        if (Application.Current is { } application)
            application.RequestedThemeVariant = _isDarkTheme ? ThemeVariant.Dark : ThemeVariant.Light;
    }

    private void DisposeCore()
    {
        try
        {
            Check(_model.Detach());
        }
        finally
        {
            DisposeNestedAdapters();
        }
    }

    private void DisposeNestedAdapters()
    {
        foreach (var item in Processes) TryDispose(item);
        foreach (var item in CpuCores) TryDispose(item);
    }

    private static void TryDispose(IDisposable? value)
    {
        try { value?.Dispose(); }
        catch { }
    }

    private int Apply(Action action) => Apply(() =>
    {
        action();
        return 0;
    });

    private int Apply(Func<int> action)
    {
        if (_batch.IsClosed) return 0;
        var hresult = 0;
        void ApplyIfAlive()
        {
            if (!_batch.IsClosed)
            {
                try { hresult = action(); }
                catch { hresult = unchecked((int)0x80004005); }
            }
        }
        try { _dispatch(ApplyIfAlive); }
        catch { return unchecked((int)0x80004005); }
        return hresult;
    }

    private static void Dispatch(Action action)
    {
        if (Dispatcher.UIThread.CheckAccess()) action();
        else Dispatcher.UIThread.Invoke(action);
    }

    private static void Check(int hresult)
    {
        if (hresult < 0) Marshal.ThrowExceptionForHR(hresult);
    }

    private void SetField<T>(ref T field, T value, [CallerMemberName] string? propertyName = null)
    {
        if (Equals(field, value)) return;
        field = value;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }

    private void SetError(string propertyName, string? message)
    {
        if (RustVmBatchErrors.Set(_errors, propertyName, message))
            ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
    }

    public sealed class DelegateCommand(Action<object?> execute) : ICommand, IRustVmBatchCommand
    {
        private bool _canExecute = true;

        public DelegateCommand(Action execute) : this(_ => execute()) { }

        public event EventHandler? CanExecuteChanged;
        public bool CanExecute(object? parameter) => _canExecute;
        public void Execute(object? parameter) => execute(parameter);

        public void SetEnabled(bool value)
        {
            if (SetEnabledCore(value)) RaiseCanExecuteChanged();
        }

        public bool SetEnabledCore(bool enabled)
        {
            if (_canExecute == enabled) return false;
            _canExecute = enabled;
            return true;
        }

        public void RaiseCanExecuteChanged() => CanExecuteChanged?.Invoke(this, EventArgs.Empty);
    }
}
